export interface PatrolLog {
  date: string; // ISO string or YYYY-MM-DD
  time: string; // HH:mm:ss
  tag: string;
  isGenerated?: boolean;
}

export interface SiteConfig {
  month: number; // 0-11
  year: number;
  roundsPerShift: number;
  tagsPerSite: number;
  nightShiftEnabled: boolean;
  dayShiftEnabled: boolean;
  nightStart: string; // HH:mm
  nightEnd: string; // HH:mm
  dayStart: string; // HH:mm
  dayEnd: string; // HH:mm
  tagNames: string[];
}

export interface ReportData {
  logs: PatrolLog[];
  summary: {
    totalLogs: number;
    importedCount: number;
    generatedCount: number;
    totalRounds: number;
  };
}

import { PatrolLog } from '../types';

/**
 * Parses a raw TXT file content.
 * Expected format: Space or tab separated containing Date (DD/MM/YYYY), Time (HH:mm:ss), and Tag Name.
 */
export const parsePatrolFile = (content: string): PatrolLog[] => {
  const lines = content.split('\n');
  const logs: PatrolLog[] = [];

  // Regex attempt: Looking for date DD/MM/YYYY or YYYY-MM-DD, then time HH:mm:ss, then the rest is the tag.
  const regex = /(\d{2,4}[/-]\d{2}[/-]\d{2,4})\s+(\d{2}:\d{2}:\d{2})\s+(.+)/;

  lines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed) return;

    const match = trimmed.match(regex);
    if (match) {
      let dateStr = match[1].replace(/\//g, '-');
      // Normalize DD-MM-YYYY to YYYY-MM-DD for easier sorting/processing
      const dateParts = dateStr.split('-');
      if (dateParts[0].length === 2) {
        dateStr = `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;
      }

      logs.push({
        date: dateStr,
        time: match[2],
        tag: match[3].trim(),
        isGenerated: false
      });
    }
  });

  return logs;
};

import { PatrolLog, SiteConfig } from '../types';

const getRandomInt = (min: number, max: number) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

const addMinutes = (timeStr: string, minutes: number): string => {
  const [h, m, s] = timeStr.split(':').map(Number);
  const date = new Date();
  date.setHours(h, m, s || 0);
  date.setMinutes(date.getMinutes() + minutes);
  return date.toTimeString().split(' ')[0];
};

const isNightShift = (timeStr: string, start: string, end: string): boolean => {
  const time = timeStr.substring(0, 5);
  if (start > end) {
    // Spans midnight (e.g., 23:00 to 06:00)
    return time >= start || time <= end;
  }
  return time >= start && time <= end;
};

export const generateMissingData = (
  existingLogs: PatrolLog[],
  config: SiteConfig
): PatrolLog[] => {
  const { 
    month, 
    year, 
    roundsPerShift, 
    tagsPerSite, 
    nightShiftEnabled, 
    dayShiftEnabled,
    nightStart,
    nightEnd,
    dayStart,
    dayEnd,
    tagNames 
  } = config;

  const allLogs: PatrolLog[] = [...existingLogs];
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  for (let day = 1; day <= daysInMonth; day++) {
    const currentDate = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

    // For each shift type, ensure target rounds are met
    const shiftsToProcess = [];
    if (nightShiftEnabled) shiftsToProcess.push({ name: 'Night', start: nightStart, end: nightEnd });
    if (dayShiftEnabled) shiftsToProcess.push({ name: 'Day', start: dayStart, end: dayEnd });

    shiftsToProcess.forEach(shift => {
      // Find existing rounds for this shift on this day
      // Note: Night shift starting at 23:00 on Day X spans into Day X+1
      const shiftLogs = allLogs.filter(log => {
        if (log.date === currentDate) {
          return isNightShift(log.time, shift.start, shift.end);
        }
        return false;
      });

      // Simple heuristic: group logs into rounds by time gaps (e.g., > 30 mins)
      let existingRoundsCount = 0;
      if (shiftLogs.length > 0) {
        const sortedLogs = [...shiftLogs].sort((a, b) => a.time.localeCompare(b.time));
        existingRoundsCount = 1;
        for (let i = 1; i < sortedLogs.length; i++) {
          const t1 = new Date(`1970-01-01T${sortedLogs[i-1].time}Z`).getTime();
          const t2 = new Date(`1970-01-01T${sortedLogs[i].time}Z`).getTime();
          if (Math.abs(t2 - t1) > 30 * 60 * 1000) {
            existingRoundsCount++;
          }
        }
      }

      const roundsToGenerate = Math.max(0, roundsPerShift - existingRoundsCount);

      for (let r = 0; r < roundsToGenerate; r++) {
        // Find a suitable start time for the new round
        // We'll calculate it based on shifting the start time
        // or finding gaps. Simple approach: distribute them.
        const hourOffset = (r + existingRoundsCount) * 2; // ~2 hours between rounds
        let baseTime = shift.start;

        // Add randomization and spacing
        const randomMinutes = getRandomInt(0, 45);
        let roundStartTime = addMinutes(baseTime, (hourOffset * 60) + randomMinutes);

        // Generate the sequence of tags
        let currentTime = roundStartTime;
        for (let t = 0; t < tagsPerSite; t++) {
          allLogs.push({
            date: currentDate,
            time: currentTime,
            tag: tagNames[t] || `Punto ${t + 1}`,
            isGenerated: true
          });
          // Next tag after 1-3 minutes
          currentTime = addMinutes(currentTime, getRandomInt(1, 3));
        }
      }
    });
  }

  // Final sort by date then time
  return allLogs.sort((a, b) => {
    if (a.date !== b.date) return a.date.localeCompare(b.date);
    return a.time.localeCompare(b.time);
  });
};

import React, { useState, useCallback, useMemo } from 'react';
