export default App;

import { PatrolLog, SiteConfig } from '../types';

const getRandomInt = (min: number, max: number) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

const timeToMinutes = (timeStr: string): number => {
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
};

const minutesToTime = (totalMinutes: number): string => {
  let normalized = totalMinutes % (24 * 60);
  if (normalized < 0) normalized += 24 * 60;
  const h = Math.floor(normalized / 60);
  const m = normalized % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:00`;
};

const getMinutesFromShiftStart = (time: string, shiftStart: string): number => {
  const tMins = timeToMinutes(time);
  const sMins = timeToMinutes(shiftStart);
  let diff = tMins - sMins;
  if (diff < 0) diff += 24 * 60;
  return diff;
};

const isWithinShift = (timeStr: string, start: string, end: string): boolean => {
  const time = timeStr.substring(0, 5);
  if (start > end) {
    return time >= start || time <= end;
  }
  return time >= start && time <= end;
};

export const generateMissingData = (
  existingLogs: PatrolLog[],
  config: SiteConfig
): PatrolLog[] => {
  const { 
    month, 
    year, 
    roundsPerShift, 
    tagsPerSite, 
    nightShiftEnabled, 
    dayShiftEnabled,
    nightStart,
    nightEnd,
    dayStart,
    dayEnd,
    tagNames 
  } = config;

  let allLogs: PatrolLog[] = [...existingLogs];
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const shiftsToProcess = [];
  if (nightShiftEnabled) shiftsToProcess.push({ name: 'Notturno', start: nightStart, end: nightEnd });
  if (dayShiftEnabled) shiftsToProcess.push({ name: 'Diurno', start: dayStart, end: dayEnd });

  for (let day = 1; day <= daysInMonth; day++) {
    const currentDate = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

    shiftsToProcess.forEach(shift => {
      // 1. Find logs that belong to this shift for this date
      const shiftLogs = allLogs.filter(log => log.date === currentDate && isWithinShift(log.time, shift.start, shift.end));

      // Sort logs chronologically relative to shift start
      const sortedLogs = [...shiftLogs].sort((a, b) => 
        getMinutesFromShiftStart(a.time, shift.start) - getMinutesFromShiftStart(b.time, shift.start)
      );

      // 2. Group existing logs into rounds (Gap > 45 mins marks a new round)
      const detectedRounds: PatrolLog[][] = [];
      if (sortedLogs.length > 0) {
        let currentRound: PatrolLog[] = [sortedLogs[0]];
        for (let i = 1; i < sortedLogs.length; i++) {
          const diff = getMinutesFromShiftStart(sortedLogs[i].time, shift.start) - getMinutesFromShiftStart(sortedLogs[i-1].time, shift.start);
          if (diff > 45) {
            detectedRounds.push(currentRound);
            currentRound = [];
          }
          currentRound.push(sortedLogs[i]);
        }
        detectedRounds.push(currentRound);
      }

      // 3. For each detected round, integrate missing tags if necessary
      detectedRounds.forEach(round => {
        const existingTags = new Set(round.map(l => l.tag));
        const firstLogTime = timeToMinutes(round[0].time);

        tagNames.slice(0, tagsPerSite).forEach((tagName, index) => {
          if (!existingTags.has(tagName)) {
            // Find an appropriate time slot (e.g., base it on previous tag or index)
            const generatedTime = minutesToTime(firstLogTime + (index * 2));
            allLogs.push({
              date: currentDate,
              time: generatedTime,
              tag: tagName,
              isGenerated: true
            });
          }
        });
      });

      // 4. Add entirely missing rounds
      const roundsToGenerateCount = Math.max(0, roundsPerShift - detectedRounds.length);

      // Calculate occupied time slots to respect 1.5 - 2h gap
      const roundStartMinutes = detectedRounds.map(r => getMinutesFromShiftStart(r[0].time, shift.start));

      for (let r = 0; r < roundsToGenerateCount; r++) {
        // Find a free window of ~120 minutes
        let startCandidate = 0;
        let found = false;

        // Try to place the round starting from shift start, advancing by 120 mins
        for (let attempt = 0; attempt < 10; attempt++) {
          const potStart = attempt * 120 + getRandomInt(0, 30);
          const isTooClose = roundStartMinutes.some(m => Math.abs(m - potStart) < 90);

          if (!isTooClose) {
            startCandidate = potStart;
            roundStartMinutes.push(startCandidate);
            found = true;
            break;
          }
        }

        if (!found) {
          // If crowded, just append at the end of the window
          startCandidate = (roundStartMinutes.length > 0 ? Math.max(...roundStartMinutes) + 120 : 30);
          roundStartMinutes.push(startCandidate);
        }

        const baseMinutes = timeToMinutes(shift.start) + startCandidate;

        tagNames.slice(0, tagsPerSite).forEach((tagName, tIdx) => {
          allLogs.push({
            date: currentDate,
            time: minutesToTime(baseMinutes + (tIdx * getRandomInt(1, 3))),
            tag: tagName,
            isGenerated: true
          });
        });
      }
    });
  }

  // Deduplicate and re-sort
  const uniqueLogsMap = new Map<string, PatrolLog>();
  allLogs.forEach(l => {
    const key = `${l.date}_${l.time}_${l.tag}`;
    if (!uniqueLogsMap.has(key) || !l.isGenerated) {
      uniqueLogsMap.set(key, l);
    }
  });

  return Array.from(uniqueLogsMap.values()).sort((a, b) => {
    if (a.date !== b.date) return a.date.localeCompare(b.date);
    return a.time.localeCompare(b.time);
  });
};

