import { PatrolLog } from '../types';

/**
 * Parsa il file TXT cercando pattern di data e ora.
 * Supporta formati come: 27/10/2023 23:15:00 NomeTag
 */
export const parsePatrolFile = (content: string): PatrolLog[] => {
  const lines = content.split('\n');
  const logs: PatrolLog[] = [];

  // Regex flessibile: Data (DD/MM/YYYY o YYYY-MM-DD), Ora (HH:mm:ss), Resto della riga come Tag
  const regex = /(\d{1,4}[/-]\d{1,2}[/-]\d{1,4})\s+(\d{1,2}:\d{1,2}:\d{1,2})\s+(.+)/;

  lines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed) return;

    const match = trimmed.match(regex);
    if (match) {
      let datePart = match[1].replace(/\//g, '-');
      const timePart = match[2];
      const tagPart = match[3].trim();

      // Normalizzazione data in YYYY-MM-DD
      const parts = datePart.split('-');
      let normalizedDate = datePart;

      if (parts[0].length <= 2) {
        // Formato DD-MM-YYYY
        normalizedDate = `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
      } else {
        // Formato YYYY-MM-DD
        normalizedDate = `${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`;
      }

      // Normalizzazione ora in HH:mm:ss
      const timeParts = timePart.split(':');
      const normalizedTime = `${timeParts[0].padStart(2, '0')}:${timeParts[1].padStart(2, '0')}:${timeParts[2].padStart(2, '0')}`;

      logs.push({
        date: normalizedDate,
        time: normalizedTime,
        tag: tagPart,
        isGenerated: false
      });
    }
  });

  return logs;
};

import { PatrolLog, SiteConfig } from '../types';

const getRandomInt = (min: number, max: number) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

const toMinutes = (timeStr: string): number => {
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
};

const fromMinutes = (totalMinutes: number): string => {
  let normalized = totalMinutes % (24 * 60);
  if (normalized < 0) normalized += 24 * 60;
  const h = Math.floor(normalized / 60);
  const m = normalized % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:00`;
};

// Controlla se un orario è all'interno della fascia, gestendo il passaggio della mezzanotte
const isTimeInRange = (time: string, start: string, end: string): boolean => {
  const t = toMinutes(time);
  const s = toMinutes(start);
  const e = toMinutes(end);

  if (s <= e) {
    return t >= s && t <= e;
  } else {
    // Range attraversa la mezzanotte (es. 23:00 - 06:00)
    return t >= s || t <= e;
  }
};

export const generateMissingData = (
  existingLogs: PatrolLog[],
  config: SiteConfig
): PatrolLog[] => {
  const { 
    month, year, roundsPerShift, tagsPerSite, 
    nightShiftEnabled, dayShiftEnabled,
    nightStart, nightEnd, dayStart, dayEnd, tagNames 
  } = config;

  let results: PatrolLog[] = [...existingLogs];
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const shifts = [];
  if (nightShiftEnabled) shifts.push({ start: nightStart, end: nightEnd });
  if (dayShiftEnabled) shifts.push({ start: dayStart, end: dayEnd });

  for (let d = 1; d <= daysInMonth; d++) {
    const currentDate = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

    shifts.forEach(shift => {
      // 1. Recupera log esistenti in questa data e fascia oraria
      const logsInShift = results.filter(l => l.date === currentDate && isTimeInRange(l.time, shift.start, shift.end));

      // Ordina i log per tempo (gestendo la precedenza logica del turno notturno)
      const sortedLogs = [...logsInShift].sort((a, b) => {
        const minA = toMinutes(a.time);
        const minB = toMinutes(b.time);
        const startMin = toMinutes(shift.start);

        let relA = minA - startMin; if (relA < 0) relA += 1440;
        let relB = minB - startMin; if (relB < 0) relB += 1440;
        return relA - relB;
      });

      // 2. Raggruppa in "Giri" esistenti (gap > 60 min tra marcatura di giri diversi)
      const roundsFound: PatrolLog[][] = [];
      if (sortedLogs.length > 0) {
        let currentGroup: PatrolLog[] = [sortedLogs[0]];
        for (let i = 1; i < sortedLogs.length; i++) {
          const minPrev = toMinutes(sortedLogs[i-1].time);
          const minCurr = toMinutes(sortedLogs[i].time);
          let diff = minCurr - minPrev; if (diff < 0) diff += 1440;

          if (diff > 60) {
            roundsFound.push(currentGroup);
            currentGroup = [];
          }
          currentGroup.push(sortedLogs[i]);
        }
        roundsFound.push(currentGroup);
      }

      // 3. Integra tag mancanti nei giri esistenti
      roundsFound.forEach(round => {
        const tagsPresenti = new Set(round.map(l => l.tag));
        const startTime = toMinutes(round[0].time);

        tagNames.slice(0, tagsPerSite).forEach((tagName, idx) => {
          if (!tagsPresenti.has(tagName)) {
            results.push({
              date: currentDate,
              time: fromMinutes(startTime + (idx * 2)),
              tag: tagName,
              isGenerated: true
            });
          }
        });
      });

      // 4. Crea giri completamente mancanti
      const roundsToCreate = Math.max(0, roundsPerShift - roundsFound.length);
      const startMinutesShift = toMinutes(shift.start);

      // Calcola orari di inizio per i nuovi giri cercando di distanziarli
      for (let r = 0; r < roundsToCreate; r++) {
        // Distanza di circa 2 ore tra un giro e l'altro
        const baseOffset = (roundsFound.length + r) * 110 + getRandomInt(5, 20);
        let currentTime = startMinutesShift + baseOffset;

        tagNames.slice(0, tagsPerSite).forEach((tagName, tIdx) => {
          results.push({
            date: currentDate,
            time: fromMinutes(currentTime + (tIdx * getRandomInt(1, 3))),
            tag: tagName,
            isGenerated: true
          });
        });
      }
    });
  }

  // Rimuovi duplicati esatti e ordina
  const finalMap = new Map<string, PatrolLog>();
  results.forEach(l => {
    const key = `${l.date}_${l.time}_${l.tag}`;
    if (!finalMap.has(key) || !l.isGenerated) {
      finalMap.set(key, l);
    }
  });

  return Array.from(finalMap.values()).sort((a, b) => {
    if (a.date !== b.date) return a.date.localeCompare(b.date);
    return a.time.localeCompare(b.time);
  });
};

