/**
 * Parsa il file TXT basandosi sul formato a punto e virgola.
 * Esclude le righe di servizio come "Fine giro ispettivo", "Inizio giro" e "SYSTEM:".
 */
export const parsePatrolFile = (content: string): PatrolLog[] => {
  const lines = content.split('\n');
  const logs: PatrolLog[] = [];

  lines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || !trimmed.includes(';')) return;

    const parts = trimmed.split(';');

    // Il timestamp è nella seconda parte (indice 1) -> "13/12/2025 02:28"
    const dateTimePart = parts[1]?.trim();

    // Cerchiamo il nome del tag nelle parti successive
    let tagPart = "";
    for (let i = 2; i < parts.length; i++) {
      const p = parts[i].trim();

      // Se troviamo una parte che contiene "Ispezione", è quasi certamente il nostro tag
      if (p.length > 5 && (p.toLowerCase().includes('ispezione') || p.toLowerCase().includes('punto'))) {
        tagPart = p;
        break;
      }

      // Fallback: se non troviamo "ispezione", prendiamo una parte testuale significativa
      if (p.length > 3 && isNaN(Number(p)) && !tagPart) {
        tagPart = p;
      }
    }

    // FILTRO RIGOROSO: Escludiamo righe di servizio, messaggi di sistema e giri non ispettivi
    const lowerTag = tagPart.toLowerCase();
    const isServiceRow = 
      lowerTag.includes('fine giro') || 
      lowerTag.includes('inizio giro') || 
      lowerTag.includes('system:') || 
      lowerTag.trim() === 'system' ||
      tagPart.trim() === ':'; // Evita tag vuoti o solo simboli

    if (isServiceRow) {
      return;
    }

    if (dateTimePart && dateTimePart.includes(' ')) {
      const [dateStr, timeStr] = dateTimePart.split(' ');

      const dateParts = dateStr.split('/');
      if (dateParts.length === 3) {
        // Formato interno YYYY-MM-DD
        const normalizedDate = `${dateParts[2]}-${dateParts[1].padStart(2, '0')}-${dateParts[0].padStart(2, '0')}`;

        // Formato interno HH:mm:ss
        const normalizedTime = timeStr.length === 5 ? `${timeStr}:00` : timeStr;

        if (tagPart && tagPart.trim() !== "") {
          logs.push({
            date: normalizedDate,
            time: normalizedTime,
            tag: tagPart.replace(/:$/, '').trim(), // Pulizia finale del tag (rimuove eventuali : alla fine)
            isGenerated: false
          });
        }
      }
    }
  });

  return logs;
};

import { PatrolLog } from '../types';

/**
 * Parsa il file TXT basandosi sul formato a punto e virgola.
 * Esclude le righe di servizio, i messaggi di sistema e i codici puramente numerici (ID tag).
 */
export const parsePatrolFile = (content: string): PatrolLog[] => {
  const lines = content.split('\n');
  const logs: PatrolLog[] = [];

  lines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || !trimmed.includes(';')) return;

    const parts = trimmed.split(';');

    // Il timestamp è nella seconda parte (indice 1) -> "13/12/2025 02:28"
    const dateTimePart = parts[1]?.trim();

    // Cerchiamo il nome del tag nelle parti successive
    let tagPart = "";

    // Cerchiamo prima esplicitamente la parte che contiene "Ispezione"
    const inspectionPart = parts.find(p => p.toLowerCase().includes('ispezione:'));
    if (inspectionPart) {
      tagPart = inspectionPart.trim();
    } else {
      // Se non c'è "Ispezione:", cerchiamo una parte testuale che non sia un numero
      for (let i = 2; i < parts.length; i++) {
        const p = parts[i].trim().replace(/:$/, ''); // Rimuove eventuali : finali per il controllo numerico

        // Escludiamo stringhe vuote, numeri puri, o stringhe troppo corte (possibili ID)
        if (p.length > 3 && isNaN(Number(p)) && !p.toLowerCase().includes('system')) {
          tagPart = p;
          break;
        }
      }
    }

    // FILTRO RIGOROSO: 
    // 1. Deve esserci un tag
    // 2. Non deve essere puramente numerico (es. "40918")
    // 3. Non deve contenere parole chiave di sistema o di servizio
    if (!tagPart) return;

    const cleanTag = tagPart.replace(/:$/, '').trim();
    const lowerTag = cleanTag.toLowerCase();

    const isInvalid = 
      !isNaN(Number(cleanTag)) || // È un numero puro
      lowerTag.includes('fine giro') || 
      lowerTag.includes('inizio giro') || 
      lowerTag.includes('system:') || 
      lowerTag === 'system' ||
      cleanTag === "" ||
      cleanTag.length < 4;

    if (isInvalid) {
      return;
    }

    if (dateTimePart && dateTimePart.includes(' ')) {
      const [dateStr, timeStr] = dateTimePart.split(' ');

      const dateParts = dateStr.split('/');
      if (dateParts.length === 3) {
        // Formato interno YYYY-MM-DD
        const normalizedDate = `${dateParts[2]}-${dateParts[1].padStart(2, '0')}-${dateParts[0].padStart(2, '0')}`;

        // Formato interno HH:mm:ss
        const normalizedTime = timeStr.length === 5 ? `${timeStr}:00` : timeStr;

        logs.push({
          date: normalizedDate,
          time: normalizedTime,
          tag: cleanTag,
          isGenerated: false
        });
      }
    }
  });

  return logs;
};

import { PatrolLog, SiteConfig } from '../types';

const getRandomInt = (min: number, max: number) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

const toMinutes = (timeStr: string): number => {
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
};

const fromMinutes = (totalMinutes: number): string => {
  let normalized = totalMinutes % (24 * 60);
  if (normalized < 0) normalized += 24 * 60;
  const h = Math.floor(normalized / 60);
  const m = normalized % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:00`;
};

/**
 * Converte una data e un'ora in un timestamp numerico (minuti dall'inizio dell'anno o simile)
 * per calcoli di distanza temporale assoluta.
 */
const getAbsoluteMinutes = (dateStr: string, timeStr: string): number => {
  const d = new Date(dateStr);
  const [h, m] = timeStr.split(':').map(Number);
  return d.getTime() / (1000 * 60) + (h * 60) + m;
};

export const generateMissingData = (
  existingLogs: PatrolLog[],
  config: SiteConfig
): PatrolLog[] => {
  const { 
    month, year, roundsPerShift, tagsPerSite, 
    nightShiftEnabled, dayShiftEnabled,
    nightStart, nightEnd, dayStart, dayEnd 
  } = config;

  let results: PatrolLog[] = [...existingLogs];
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  // Tag da utilizzare
  const uniqueTagsInFile = Array.from(new Set(existingLogs.map(l => l.tag)));
  const baseTagNames = uniqueTagsInFile.length > 0 ? uniqueTagsInFile : config.tagNames;
  const targetTags = baseTagNames.slice(0, tagsPerSite);

  // Per ogni giorno del mese, definiamo l'inizio dei turni previsti
  for (let d = 1; d <= daysInMonth; d++) {
    const currentDateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

    const activeShifts = [];
    if (nightShiftEnabled) activeShifts.push({ start: nightStart, end: nightEnd, type: 'NIGHT' });
    if (dayShiftEnabled) activeShifts.push({ start: dayStart, end: dayEnd, type: 'DAY' });

    activeShifts.forEach(shift => {
      // Calcoliamo l'intervallo temporale assoluto del turno
      const shiftStartAbs = getAbsoluteMinutes(currentDateStr, shift.start);
      let shiftEndAbs = getAbsoluteMinutes(currentDateStr, shift.end);

      // Se l'ora di fine è minore di quella di inizio (es. 22:00 -> 06:00), il turno finisce il giorno dopo
      if (toMinutes(shift.end) <= toMinutes(shift.start)) {
        shiftEndAbs += (24 * 60);
      }

      // Troviamo i log che cadono in questo specifico turno (finestra temporale reale)
      const logsInShift = results.filter(l => {
        const logAbs = getAbsoluteMinutes(l.date, l.time);
        return logAbs >= shiftStartAbs && logAbs <= shiftEndAbs;
      }).sort((a, b) => getAbsoluteMinutes(a.date, a.time) - getAbsoluteMinutes(b.date, b.time));

      // Raggruppiamo i log in giri (un giro è una sequenza di tag vicini nel tempo)
      const roundsFound: PatrolLog[][] = [];
      if (logsInShift.length > 0) {
        let currentRound: PatrolLog[] = [logsInShift[0]];
        for (let i = 1; i < logsInShift.length; i++) {
          const diff = getAbsoluteMinutes(logsInShift[i].date, logsInShift[i].time) - 
                       getAbsoluteMinutes(logsInShift[i-1].date, logsInShift[i-1].time);

          if (diff > 45) { // Se passano più di 45 min, consideriamo iniziato un nuovo giro
            roundsFound.push(currentRound);
            currentRound = [];
          }
          currentRound.push(logsInShift[i]);
        }
        roundsFound.push(currentRound);
      }

      // 1. Integriamo i tag mancanti nei giri che la pattuglia ha già iniziato
      roundsFound.forEach(round => {
        const tagsPresenti = new Set(round.map(l => l.tag));
        const firstLog = round[0];
        const roundStartTimeAbs = getAbsoluteMinutes(firstLog.date, firstLog.time);

        targetTags.forEach((tagName, idx) => {
          if (!tagsPresenti.has(tagName)) {
            const newTimeAbs = roundStartTimeAbs + (idx * 2);
            // Calcoliamo data e ora corretta anche se il tag finisce dopo mezzanotte
            const newDate = new Date(newTimeAbs * 60 * 1000);
            results.push({
              date: newDate.toISOString().split('T')[0],
              time: fromMinutes(toMinutes(newDate.toISOString().split('T')[1].substring(0, 5))),
              tag: tagName,
              isGenerated: true
            });
          }
        });
      });

      // 2. Creiamo i giri mancanti per arrivare al numero richiesto (es. 3 giri)
      const roundsToCreate = Math.max(0, roundsPerShift - roundsFound.length);

      // Calcoliamo da dove iniziare a generare i giri mancanti
      let nextRoundStartAbs = roundsFound.length > 0 
        ? getAbsoluteMinutes(roundsFound[roundsFound.length - 1][0].date, roundsFound[roundsFound.length - 1][0].time) + 120
        : shiftStartAbs + 30;

      for (let r = 0; r < roundsToCreate; r++) {
        // Se il tempo di generazione supera la fine del turno, ci fermiamo
        if (nextRoundStartAbs > shiftEndAbs - 30) break;

        let currentTimeAbs = nextRoundStartAbs;
        targetTags.forEach((tagName, tIdx) => {
          const tagTimeAbs = currentTimeAbs + (tIdx * getRandomInt(1, 3));
          const tagDate = new Date(tagTimeAbs * 60 * 1000);

          results.push({
            date: tagDate.toISOString().split('T')[0],
            time: fromMinutes(toMinutes(tagDate.toISOString().split('T')[1].substring(0, 5))),
            tag: tagName,
            isGenerated: true
          });
        });

        // Distanziamo il prossimo giro di circa 1.5 - 2 ore
        nextRoundStartAbs += (100 + getRandomInt(0, 30));
      }
    });
  }

  // Pulizia finale e ordinamento
  const finalMap = new Map<string, PatrolLog>();
  results.forEach(l => {
    const key = `${l.date}_${l.time.substring(0, 5)}_${l.tag}`;
    if (!finalMap.has(key) || !l.isGenerated) finalMap.set(key, l);
  });

  return Array.from(finalMap.values()).sort((a, b) => {
    const absA = getAbsoluteMinutes(a.date, a.time);
    const absB = getAbsoluteMinutes(b.date, b.time);
    return absA - absB;
  });
};

import { PatrolLog, SiteConfig } from '../types';

const getRandomInt = (min: number, max: number) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

const toMinutes = (timeStr: string): number => {
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
};

const fromMinutes = (totalMinutes: number): string => {
  let normalized = totalMinutes % (24 * 60);
  if (normalized < 0) normalized += 24 * 60;
  const h = Math.floor(normalized / 60);
  const m = normalized % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:00`;
};

/**
 * Calcola i minuti assoluti partendo da una data ISO e una stringa orario.
 * Fondamentale per calcoli che attraversano la mezzanotte.
 */
const getAbsoluteMinutes = (dateStr: string, timeStr: string): number => {
  const [year, month, day] = dateStr.split('-').map(Number);
  const [h, m] = timeStr.split(':').map(Number);
  // Usiamo Date.UTC per evitare problemi di fuso orario durante i calcoli
  const d = new Date(Date.UTC(year, month - 1, day, h, m));
  return d.getTime() / (1000 * 60);
};

export const generateMissingData = (
  existingLogs: PatrolLog[],
  config: SiteConfig
): PatrolLog[] => {
  const { 
    month, year, roundsPerShift, tagsPerSite, 
    nightShiftEnabled, dayShiftEnabled,
    nightStart, nightEnd, dayStart, dayEnd 
  } = config;

  let results: PatrolLog[] = [...existingLogs];
  // Numero di giorni nel mese selezionato
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  // Determiniamo i tag da usare (priorità a quelli trovati nel file)
  const uniqueTagsInFile = Array.from(new Set(existingLogs.map(l => l.tag)));
  const baseTagNames = uniqueTagsInFile.length > 0 ? uniqueTagsInFile : config.tagNames;
  const targetTags = baseTagNames.slice(0, tagsPerSite);

  // Iteriamo su ogni giorno del mese partendo dal GIORNO 1
  for (let d = 1; d <= daysInMonth; d++) {
    const currentDateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

    const shiftsToProcess = [];
    if (nightShiftEnabled) shiftsToProcess.push({ start: nightStart, end: nightEnd, type: 'NIGHT' });
    if (dayShiftEnabled) shiftsToProcess.push({ start: dayStart, end: dayEnd, type: 'DAY' });

    shiftsToProcess.forEach(shift => {
      // Finestra temporale ufficiale del turno
      const shiftStartAbs = getAbsoluteMinutes(currentDateStr, shift.start);
      let shiftEndAbs = getAbsoluteMinutes(currentDateStr, shift.end);
      if (toMinutes(shift.end) <= toMinutes(shift.start)) {
        shiftEndAbs += (24 * 60); // Turno notturno: finisce il giorno dopo
      }

      /**
       * TOLLERANZA: Spesso la pattuglia passa un po' prima dell'inizio ufficiale (es. 22:30 per turno delle 23:00).
       * Estendiamo la ricerca dei log esistenti di 90 minuti prima dell'inizio del turno.
       */
      const detectionStartAbs = shiftStartAbs - 90;
      const detectionEndAbs = shiftEndAbs + 30;

      // Cerchiamo i log che cadono in questa finestra (inclusa tolleranza)
      const logsInShift = results.filter(l => {
        const logAbs = getAbsoluteMinutes(l.date, l.time);
        return logAbs >= detectionStartAbs && logAbs <= detectionEndAbs;
      }).sort((a, b) => getAbsoluteMinutes(a.date, a.time) - getAbsoluteMinutes(b.date, b.time));

      // Identifichiamo i giri esistenti (gap > 45 min tra tag indica un nuovo giro)
      const roundsFound: PatrolLog[][] = [];
      if (logsInShift.length > 0) {
        let currentRound: PatrolLog[] = [logsInShift[0]];
        for (let i = 1; i < logsInShift.length; i++) {
          const diff = getAbsoluteMinutes(logsInShift[i].date, logsInShift[i].time) - 
                       getAbsoluteMinutes(logsInShift[i-1].date, logsInShift[i-1].time);
          if (diff > 45) {
            roundsFound.push(currentRound);
            currentRound = [];
          }
          currentRound.push(logsInShift[i]);
        }
        roundsFound.push(currentRound);
      }

      /**
       * FASE 1: Completamento dei giri esistenti.
       * Se la pattuglia ha fatto un giro parziale, aggiungiamo i tag mancanti lì invece di creare un nuovo giro.
       */
      roundsFound.forEach(round => {
        const tagsPresenti = new Set(round.map(l => l.tag));
        const firstLog = round[0];
        const roundStartTimeAbs = getAbsoluteMinutes(firstLog.date, firstLog.time);

        targetTags.forEach((tagName, idx) => {
          if (!tagsPresenti.has(tagName)) {
            const newTimeAbs = roundStartTimeAbs + (idx * 1.5); // Tag distanziati di 1-2 min
            const newDate = new Date(newTimeAbs * 60 * 1000);
            results.push({
              date: newDate.toISOString().split('T')[0],
              time: fromMinutes(toMinutes(newDate.toISOString().split('T')[1].substring(0, 5))),
              tag: tagName,
              isGenerated: true
            });
          }
        });
      });

      /**
       * FASE 2: Creazione giri mancanti.
       * Se i giri trovati (inclusi quelli fatti in anticipo) sono inferiori al richiesto, ne creiamo di nuovi.
       */
      const roundsToCreate = Math.max(0, roundsPerShift - roundsFound.length);

      if (roundsToCreate > 0) {
        // Calcoliamo lo spazio temporale disponibile per distribuire i giri
        let currentGenerationTimeAbs = shiftStartAbs + 45; // Iniziamo 45 min dopo l'inizio del turno

        for (let r = 0; r < roundsToCreate; r++) {
          // Evitiamo di generare giri troppo vicini a quelli reali esistenti
          const isTooCloseToExisting = roundsFound.some(round => {
             const rStart = getAbsoluteMinutes(round[0].date, round[0].time);
             return Math.abs(currentGenerationTimeAbs - rStart) < 90;
          });

          if (isTooCloseToExisting) {
            currentGenerationTimeAbs += 120; // Saltiamo avanti se siamo troppo vicini a un giro reale
            r--; // Riprova a generare questo giro più tardi
            if (currentGenerationTimeAbs > shiftEndAbs - 30) break;
            continue;
          }

          // Verifichiamo di non aver superato la fine del turno
          if (currentGenerationTimeAbs > shiftEndAbs - 30) break;

          targetTags.forEach((tagName, tIdx) => {
            const tagTimeAbs = currentGenerationTimeAbs + (tIdx * getRandomInt(1, 2));
            const tagDate = new Date(tagTimeAbs * 60 * 1000);
            results.push({
              date: tagDate.toISOString().split('T')[0],
              time: fromMinutes(toMinutes(tagDate.toISOString().split('T')[1].substring(0, 5))),
              tag: tagName,
              isGenerated: true
            });
          });

          currentGenerationTimeAbs += (120 + getRandomInt(0, 40)); // Distanziamo i giri di circa 2 ore
        }
      }
    });
  }

  // Rimozione duplicati esatti e ordinamento finale
  const finalMap = new Map<string, PatrolLog>();
  results.forEach(l => {
    // La chiave include data, ora (HH:mm) e tag per evitare doppioni generati sopra quelli reali
    const key = `${l.date}_${l.time.substring(0, 5)}_${l.tag}`;
    if (!finalMap.has(key) || !l.isGenerated) {
      finalMap.set(key, l);
    }
  });

  return Array.from(finalMap.values()).sort((a, b) => {
    const timeA = new Date(`${a.date}T${a.time}`).getTime();
    const timeB = new Date(`${b.date}T${b.time}`).getTime();
    return timeA - timeB;
  });
};

