import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { parsePatrolFile } from './utils/parser';
import { generateMissingData } from './utils/generator';
import { PatrolLog, SiteConfig, ReportData } from './types';

const Card: React.FC<{ children: React.ReactNode, title?: string, icon?: string, className?: string }> = ({ children, title, icon, className = "" }) => (
  <div className={`glass p-6 rounded-2xl neon-border transition-all duration-300 ${className}`}>
    {title && (
      <div className="flex items-center mb-6 border-b border-sky-500/20 pb-4">
        {icon && <i className={`${icon} text-sky-400 mr-3 text-xl`}></i>}
        <h2 className="text-xl font-orbitron font-bold text-sky-100 uppercase tracking-widest">{title}</h2>
      </div>
    )}
    {children}
  </div>
);

const App: React.FC = () => {
  const [logs, setLogs] = useState<PatrolLog[]>([]);
  const [config, setConfig] = useState<SiteConfig>({
    month: new Date().getMonth(),
    year: new Date().getFullYear(),
    roundsPerShift: 3,
    tagsPerSite: 16,
    nightShiftEnabled: true,
    dayShiftEnabled: false,
    nightStart: "23:00",
    nightEnd: "06:00",
    dayStart: "08:00",
    dayEnd: "17:00",
    tagNames: Array.from({ length: 32 }, (_, i) => `Punto ${i + 1}`),
    tagIntervalMin: 1,
    tagIntervalMax: 3
  });
  const [isProcessing, setIsProcessing] = useState(false);
  const [aiSummary, setAiSummary] = useState<string>("");

  useEffect(() => {
    if (logs.length > 0) {
      const firstImported = logs.find(l => !l.isGenerated);
      if (firstImported) {
        const d = new Date(firstImported.date);
        if (!isNaN(d.getTime())) {
          setConfig(prev => ({ ...prev, month: d.getMonth(), year: d.getFullYear() }));
        }
      }
    }
  }, [logs.length]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      const parsedLogs = parsePatrolFile(content);
      if (parsedLogs.length === 0) {
        setAiSummary("File caricato ma nessun dato reale trovato. Il sistema genererà i dati da zero.");
        setLogs([]);
      } else {
        setLogs(parsedLogs);
        setAiSummary(`Caricati ${parsedLogs.length} passaggi reali.`);
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const processReport = async () => {
    setIsProcessing(true);
    await new Promise(r => setTimeout(r, 1000));

    try {
      // Ora generateMissingData viene chiamata anche se logs è vuoto
      const completeLogs = generateMissingData(logs, config);
      setLogs(completeLogs);

      if (logs.length === 0) {
        setAiSummary(`Generazione completa per ${new Date(config.year, config.month).toLocaleString('it-IT', { month: 'long', year: 'numeric' })}: creati tutti i turni da zero.`);
      } else {
        setAiSummary(`Integrazione completata. I dati reali sono stati mantenuti e quelli mancanti sono stati aggiunti.`);
      }
    } catch (err) {
      console.error(err);
      setAiSummary("Errore durante l'elaborazione dei dati.");
    } finally {
      setIsProcessing(false);
    }
  };

  const clearData = () => {
    setLogs([]);
    setAiSummary("Dati resettati. Pronto per una nuova generazione.");
  };

  const exportToExcel = () => {
    // @ts-ignore
    if (!window.XLSX) return;
    const data = logs.map(l => ({ 
      Data: l.date.split('-').reverse().join('/'), 
      Ora: l.time.substring(0, 5), 
      'Punto Ispezione': l.tag,
      'Fonte': l.isGenerated ? 'AUTOMATICO' : 'REALE'
    }));
    // @ts-ignore
    const ws = window.XLSX.utils.json_to_sheet(data);
    // @ts-ignore
    const wb = window.XLSX.utils.book_new();
    // @ts-ignore
    window.XLSX.utils.book_append_sheet(wb, ws, "Report_Pattuglia");
    // @ts-ignore
    window.XLSX.writeFile(wb, `Report_PatrolGuard_${config.year}_${config.month + 1}.xlsx`);
  };

  const stats = useMemo(() => {
    const imported = logs.filter(l => !l.isGenerated).length;
    const generated = logs.filter(l => l.isGenerated).length;
    return { imported, generated, total: logs.length };
  }, [logs]);

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center">
      <header className="w-full max-w-7xl flex flex-col md:flex-row justify-between items-center mb-10 gap-6">
        <div className="flex items-center">
          <div className="w-12 h-12 bg-sky-500 rounded-lg flex items-center justify-center mr-4 shadow-[0_0_20px_rgba(14,165,233,0.5)]">
            <i className="fas fa-shield-halved text-2xl text-white"></i>
          </div>
          <div>
            <h1 className="text-3xl font-orbitron font-black glow-text tracking-tighter uppercase">
              Patrol<span className="text-sky-400">Guard</span> AI
            </h1>
            <p className="text-sky-500/60 uppercase text-[10px] tracking-[0.4em] font-bold mt-1">Advanced Tactical Analysis</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <label className="neon-btn text-white px-6 py-3 rounded-full cursor-pointer flex items-center font-bold uppercase text-xs tracking-widest">
            <i className="fas fa-upload mr-2"></i> 1. Importa TXT
            <input type="file" className="hidden" accept=".txt" onChange={handleFileUpload} />
          </label>
          <button 
            onClick={processReport}
            disabled={isProcessing}
            className={`px-6 py-3 rounded-full flex items-center font-bold uppercase text-xs tracking-widest transition-all duration-300 ${isProcessing ? 'bg-slate-800 text-slate-500 border border-slate-700 cursor-not-allowed' : 'bg-transparent border border-sky-400 text-sky-400 hover:bg-sky-400/10'}`}
          >
            <i className={`fas ${isProcessing ? 'fa-spinner fa-spin' : 'fa-bolt'} mr-2`}></i> 
            {logs.length === 0 ? "2. Genera Tutto" : "2. Elabora Report"}
          </button>
          {logs.length > 0 && (
            <button onClick={clearData} className="text-slate-500 hover:text-red-400 transition-colors p-2">
              <i className="fas fa-trash-alt"></i>
            </button>
          )}
        </div>
      </header>

      <main className="w-full max-w-7xl grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 flex flex-col gap-6">
          <Card title="Configurazione" icon="fas fa-cog">
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div>
