          </div>
          <div>
            <h1 className="text-3xl font-orbitron font-black glow-text tracking-tighter uppercase">
              Patrol<span className="text-sky-400">Guard</span> Pro
            </h1>
          </div>
        </div>
        <div className="flex items-center gap-4">
